export type ParsedSettleSessionUsageInstruction<
  TProgram extends string = typeof BLOCKROUTER_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    relayer: TAccountMetas[0];
    vault: TAccountMetas[1];
    vaultAta: TAccountMetas[2];
    session: TAccountMetas[3];
    model: TAccountMetas[4];
    config: TAccountMetas[5];
    providerAta: TAccountMetas[6];
    tokenProgram: TAccountMetas[7];
    mint: TAccountMetas[8];
    beneficiary: TAccountMetas[9];
  };
  data: SettleSessionUsageInstructionData;
};

export function parseSettleSessionUsageInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedSettleSessionUsageInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 10) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 10,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      relayer: getNextAccount(),
      vault: getNextAccount(),
      vaultAta: getNextAccount(),
      session: getNextAccount(),
      model: getNextAccount(),
      config: getNextAccount(),
      providerAta: getNextAccount(),
      tokenProgram: getNextAccount(),
      mint: getNextAccount(),
      beneficiary: getNextAccount(),
    },
    data: getSettleSessionUsageInstructionDataDecoder().decode(
      instruction.data,
    ),
  };
}
